etPassword($a,$b){$b=(string)$b;if($b===''){return'';}if(strlen($b)<6){return'新密码至少 6 位。';}if(!self::ensureTables()){return'数据表不可用。';}try{$c=DB::pdo()->prepare('UPDATE `'.self::T_USER.'` SET `pass_hash`=:p, `fail_count`=0, `lock_until`=NULL WHERE `id`=:id');$c->execute(array(':p'=>password_hash($b,PASSWORD_DEFAULT),':id'=>(int)$a));return'';}catch(\Exception $d){return $d->getMessage();}}public static function findByEmail($a){if(!self::ensureTables()){return null;}$a=trim((string)$a);if($a===''){return null;}try{$b=DB::pdo()->prepare('SELECT * FROM `'.self::T_USER.'` WHERE `email`=:e ORDER BY `id` ASC LIMIT 1');$b->execute(array(':e'=>$a));$c=$b->fetch();return $c?$c:null;}catch(\Exception $d){return null;}}public static function changePassword($a,$b,$c,$d){$e=self::findById($a);if(!$e){return self::fail('登录状态已失效，请重新登录。');}if(!password_verify((string)$b,(string)$e['pass_hash'])){return self::fail('当前密码不正确。');}$f=self::validPassword($c,(string)$e['username']);if($f!==''){return self::fail($f);}if((string)$c!==(string)$d){return self::fail('两次输入的新密码不一致。');}if((string)$c===(string)$b){return self::fail('新密码不能和当前密码相同。');}try{$g=DB::pdo()->prepare('UPDATE `'.self::T_USER.'` SET `pass_hash`=:p, `fail_count`=0, `lock_until`=NULL WHERE `id`=:id');$g->execute(array(':p'=>password_hash((string)$c,PASSWORD_DEFAULT),':id'=>(int)$a));}catch(\Exception $h){return self::fail('修改失败：'.$h->getMessage());}return array('ok'=>true,'msg'=>'密码已更新，请用新密码登录。','uid'=>(int)$a);}public static function saveEmail($a,$b){$c=self::findById($a);if(!$c){return self::fail('登录状态已失效，请重新登录。');}$b=trim((string)$b);$d=self::validEmail($b);if($d!==''){return self::fail($d);}try{$e=DB::pdo()->prepare('UPDATE `'.self::T_USER.'` SET `email`=:e WHERE `id`=:id');$e->execute(array(':e'=>$b,':id'=>(int)$a));}catch(\Exception $f){return self::fail('保存失败：'.$f->getMessage());}return array('ok'=>true,'msg'=>'邮箱已保存。','uid'=>(int)$a);}public static function requestReset($a,$b='user'){$b=($b==='admin')?'admin':'user';if(